import json,hashlib,datetime,os,html,re,shutil
R=Path(__file__).resolve().parents[1];pending=json.loads((R/'artifacts/asic_cleanup_pending.json').read_text());P=Path(pending['plan']);plan=json.loads(P.read_text());BIN=Path(plan['bin']);AF=R/'artifacts/analog_asic/final';D1=R/'artifacts/ASIC/final';DX=R/'artifacts/ASIC_XL/final'
def sha(p):
 h=hashlib.sha256()
 with p.open('rb') as f:
  for b in iter(lambda:f.read(8*1024*1024),b''):h.update(b)
 return h.hexdigest()
def dump(p,j):p.parent.mkdir(parents=True,exist_ok=True);p.write_text(json.dumps(j,indent=2)+'\n',encoding='utf-8')
assert json.loads((BIN/'move_status.json').read_text(encoding='utf-8-sig'))['status']=='moves_completed_pending_hash_and_accounting'
errors=[]
for a in plan['original_files']:
 p=R/a['current']
 if not os.path.lexists(p):errors.append({'original':a['original'],'error':'missing retained/archive file','expected':a['current']})
 elif p.lstat().st_size!=a['bytes']:errors.append({'original':a['original'],'error':'size changed'})
print(json.dumps({'original_files_accounted':plan['original_file_count'],'accounting_errors':len(errors)}),flush=True)
verified=[]
for i,a in enumerate(plan['retained_files']):
 p=R/a['current'];h=sha(p)
 if h!=a['sha256']:errors.append({'original':a['original'],'error':'retained SHA256 mismatch'})
 verified.append(dict(a,verified_sha256=h))
 if (i+1)%500==0:print('Retained hashes checked: '+str(i+1),flush=True)
dump(BIN/'integrity_audit.json',{'all_original_files_accounted':not errors,'original_file_count':plan['original_file_count'],'retained_hashes_checked':len(verified),'errors':errors,'checked_UTC':datetime.datetime.now(datetime.timezone.utc).isoformat()});assert not errors,errors[:5]
paths={a['original']:a['current'] for a in plan['retained_files']};archive_root=BIN.relative_to(R).as_posix();root_rels=[Path(a['source']).relative_to(R).as_posix() for a in plan['roots']]
def locate(s):
 if not isinstance(s,str):return s
 norm=s.replace('\\','/')
 if norm.startswith('/workspace/'):norm=norm[11:]
 rp=R.as_posix()+'/'
 if norm.lower().startswith(rp.lower()):norm=norm[len(rp):]
 if norm in paths:return paths[norm]
 for root in root_rels:
  if norm==root or norm.startswith(root+'/'):return archive_root+'/'+norm
 return s
def relocate(x):
 if isinstance(x,dict):return {locate(k):relocate(v) for k,v in x.items()}
 if isinstance(x,list):return [relocate(v) for v in x]
 if isinstance(x,str):return locate(x)
 return x
