for root,title,claim in [(AF,'EventSpikeSeg140k GF180 analog — final article package','Full hierarchical research layout and representative consumption delivered; no manufacture/full-chip timing or power signoff.'),(D1,'EventSpikeSeg140k digital — final reference snapshot','Documentation of the last checkpoint-exact exports and completed block views. No complete digital full-chip layout.'),(DX,'EventSpikeSegXL digital — final reference snapshot','Documentation of the last XL exports, structural hierarchy and completed block views. Full-chip implementation remained incomplete.')]:
 files=[a for a in verified if a['current'].startswith(root.relative_to(R).as_posix()+'/')];dump(root/'package_manifest.json',{'title':title,'claim_boundary':claim,'retained_original_files':files,'source_relocation_index':'artifacts/asic_artifact_index.json','review_bin':archive_root,'bytes_verified_unchanged':True})
